/**
 * @name Command injection via subprocess/os.system
 * @description Using subprocess or os.system with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find calls to os.system, subprocess.call, subprocess.run, etc.
    exists(API::CallNode call |
      // os.system
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // subprocess.call
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // subprocess.run
      call = API::moduleImport("subprocess").getMember("run").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // subprocess.Popen
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // subprocess.check_output
      call = API::moduleImport("subprocess").getMember("check_output").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // subprocess.check_call
      call = API::moduleImport("subprocess").getMember("check_call").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Insecure reflection via getattr/setattr/__import__
 * @description Using getattr, setattr, hasattr, or __import__ with untrusted input can lead to arbitrary attribute access or module loading
 * @kind path-problem
 * @problem.severity error
 * @id py/insecure-reflection
 * @tags security
 *        external/cwe/cwe-470
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ReflectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find calls to getattr, setattr, hasattr, __import__
    exists(API::CallNode call |
      // getattr
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
    or
    exists(API::CallNode call |
      // setattr
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
    or
    exists(API::CallNode call |
      // hasattr
      call = API::builtin("hasattr").getACall() and
      sink = call.getArg(1)
    )
    or
    exists(API::CallNode call |
      // __import__
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // importlib.import_module
      call = API::moduleImport("importlib").getMember("import_module").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReflectionFlow = TaintTracking::Global<ReflectionConfig>;
import ReflectionFlow::PathGraph

from ReflectionFlow::PathNode source, ReflectionFlow::PathNode sink
where ReflectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure reflection from $@.", source.getNode(), "user input"

